import type { LucideIcon } from 'lucide-react'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

export type AboutValue = {
  title: string
  description: string
  icon?: LucideIcon
}

export type AboutValuesSectionProps = {
  eyebrow?: string
  title: string
  description: string
  values: AboutValue[]
  statement?: string
  className?: string
}

export function AboutValuesSection({
  eyebrow = 'Sobre nós',
  title,
  description,
  values,
  statement,
  className,
}: AboutValuesSectionProps) {
  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <div className="grid gap-10 lg:grid-cols-[0.9fr_1.1fr] lg:gap-16">
          <header className="lg:sticky lg:top-24 lg:self-start">
            <p className="text-sm font-semibold uppercase tracking-[0.18em] text-primary">
              {eyebrow}
            </p>
            <h2 className="mt-4 text-balance text-3xl font-bold tracking-tight md:text-5xl">
              {title}
            </h2>
            <p className="mt-5 max-w-xl text-lg leading-8 text-muted-foreground">{description}</p>
            {statement ? (
              <p className="mt-8 border-l-2 border-primary pl-5 text-lg font-medium leading-8">
                {statement}
              </p>
            ) : null}
          </header>

          <div className="grid gap-4 sm:grid-cols-2">
            {values.map((value, index) => {
              const Icon = value.icon
              return (
                <article
                  key={value.title}
                  className={cn(
                    'group min-h-56 rounded-3xl border bg-card p-6 transition duration-300 hover:border-primary/30 hover:shadow-lg',
                    index === 0 && 'sm:col-span-2 sm:min-h-64',
                  )}
                >
                  <div className="flex items-start justify-between">
                    <span className="flex size-11 items-center justify-center rounded-2xl bg-primary/10 text-primary">
                      {Icon ? <Icon className="size-5" aria-hidden="true" /> : `0${index + 1}`}
                    </span>
                    <ArrowUpRight
                      className="size-5 text-muted-foreground transition group-hover:-translate-y-1 group-hover:translate-x-1 group-hover:text-primary motion-reduce:transform-none"
                      aria-hidden="true"
                    />
                  </div>
                  <h3 className="mt-10 text-xl font-semibold">{value.title}</h3>
                  <p className="mt-3 leading-7 text-muted-foreground">{value.description}</p>
                </article>
              )
            })}
          </div>
        </div>
      </div>
    </section>
  )
}

import type { ReactNode } from 'react'
import Link from 'next/link'
import { ArrowUpRight, Check } from 'lucide-react'

import { cn } from '@/lib/utils'

export type DifferentialsSectionItem = {
  title: string
  description: string
  icon?: ReactNode
  eyebrow?: string
  points?: readonly string[]
}

export type DifferentialsSectionProps = {
  eyebrow?: string
  title: string
  description?: string
  items: readonly DifferentialsSectionItem[]
  variant?: 'cards' | 'numbered' | 'split' | 'spotlight'
  columns?: 2 | 3 | 4
  action?: { label: string; href: string }
  className?: string
}

export function DifferentialsSection({
  eyebrow,
  title,
  description,
  items,
  variant = 'cards',
  columns = 3,
  action,
  className,
}: DifferentialsSectionProps) {
  const dark = variant === 'spotlight'
  const columnsClass = {
    2: 'md:grid-cols-2',
    3: 'md:grid-cols-2 lg:grid-cols-3',
    4: 'md:grid-cols-2 xl:grid-cols-4',
  }[columns]

  return (
    <section
      className={cn(
        'overflow-hidden py-20 md:py-28',
        dark ? 'bg-slate-950 text-white' : 'bg-background',
        className,
      )}
    >
      <div
        className={cn(
          'container',
          variant === 'split' && 'grid gap-12 lg:grid-cols-[.78fr_1.22fr] lg:gap-20',
        )}
      >
        <header
          className={cn(
            'max-w-2xl',
            variant !== 'split' && 'mb-12',
            variant === 'split' && 'h-fit lg:sticky lg:top-28',
          )}
        >
          {eyebrow ? (
            <p className="text-xs font-bold uppercase tracking-[0.24em] text-primary">{eyebrow}</p>
          ) : null}
          <h2 className="mt-4 text-3xl font-bold tracking-tight md:text-5xl">{title}</h2>
          {description ? (
            <p
              className={cn(
                'mt-5 text-base leading-8',
                dark ? 'text-white/60' : 'text-muted-foreground',
              )}
            >
              {description}
            </p>
          ) : null}
          {action ? (
            <Link
              href={action.href}
              className="mt-7 inline-flex items-center gap-2 rounded-sm font-semibold text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              {action.label}
              <ArrowUpRight className="h-4 w-4" aria-hidden />
            </Link>
          ) : null}
        </header>

        <div
          className={cn(
            variant === 'cards' && `grid gap-5 ${columnsClass}`,
            variant === 'numbered' && 'divide-y border-y',
            variant === 'split' && 'space-y-4',
            variant === 'spotlight' && `grid gap-5 ${columnsClass}`,
          )}
        >
          {items.map((item, index) => (
            <article
              key={`${item.title}-${index}`}
              className={cn(
                'group relative',
                variant === 'cards' &&
                  'rounded-3xl border bg-card p-7 shadow-sm transition duration-300 hover:-translate-y-1 hover:border-primary/40 hover:shadow-xl',
                variant === 'numbered' &&
                  'grid gap-5 py-8 md:grid-cols-[80px_1fr_1.2fr] md:items-start',
                variant === 'split' &&
                  'rounded-3xl border bg-card p-7 transition hover:border-primary/40 hover:shadow-lg md:p-8',
                variant === 'spotlight' &&
                  'isolate overflow-hidden rounded-3xl border border-white/10 bg-white/[0.04] p-7 duration-300 before:absolute before:-right-16 before:-top-16 before:-z-10 before:h-44 before:w-44 before:rounded-full before:bg-primary/10 before:blur-3xl before:transition hover:-translate-y-1 hover:border-primary/40 hover:before:bg-primary/25',
              )}
            >
              {variant === 'numbered' ? (
                <span className="text-sm font-bold tracking-[0.2em] text-primary">
                  {String(index + 1).padStart(2, '0')}
                </span>
              ) : item.icon ? (
                <span
                  className={cn(
                    'mb-6 flex h-12 w-12 items-center justify-center rounded-2xl',
                    dark ? 'bg-white/10 text-primary' : 'bg-primary/10 text-primary',
                  )}
                >
                  {item.icon}
                </span>
              ) : (
                <span className="mb-6 block text-sm font-bold tracking-[0.2em] text-primary">
                  {String(index + 1).padStart(2, '0')}
                </span>
              )}

              <div>
                {item.eyebrow ? (
                  <p
                    className={cn(
                      'text-xs font-bold uppercase tracking-[0.18em]',
                      dark ? 'text-white/45' : 'text-muted-foreground',
                    )}
                  >
                    {item.eyebrow}
                  </p>
                ) : null}
                <h3 className={cn('text-xl font-semibold', item.eyebrow && 'mt-2')}>
                  {item.title}
                </h3>
              </div>

              <div>
                <p
                  className={cn(
                    'leading-7',
                    variant === 'numbered' ? 'text-sm' : 'mt-3 text-sm',
                    dark ? 'text-white/60' : 'text-muted-foreground',
                  )}
                >
                  {item.description}
                </p>
                {item.points?.length ? (
                  <ul className="mt-5 space-y-2">
                    {item.points.map((point) => (
                      <li key={point} className="flex items-start gap-2 text-sm">
                        <Check className="mt-0.5 h-4 w-4 shrink-0 text-primary" aria-hidden />
                        <span className={dark ? 'text-white/70' : 'text-muted-foreground'}>
                          {point}
                        </span>
                      </li>
                    ))}
                  </ul>
                ) : null}
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  )
}

import { cn } from '@/lib/utils'

export type StatsGridProps = {
  title?: string
  description?: string
  stats: Array<{ value: string; label: string; detail?: string }>
  columns?: 2 | 3 | 4
  className?: string
}

export function StatsGrid({ title, description, stats, columns = 4, className }: StatsGridProps) {
  const columnClass = {
    2: 'md:grid-cols-2',
    3: 'md:grid-cols-3',
    4: 'md:grid-cols-2 lg:grid-cols-4',
  }[columns]
  return (
    <section
      className={cn('py-16 md:py-24', className)}
      aria-labelledby={title ? 'stats-title' : undefined}
    >
      <div className="container">
        {title ? (
          <h2 id="stats-title" className="text-3xl font-bold tracking-tight md:text-4xl">
            {title}
          </h2>
        ) : null}
        {description ? <p className="mt-3 max-w-2xl text-muted-foreground">{description}</p> : null}
        <dl
          className={cn(
            'mt-10 grid gap-px overflow-hidden rounded-2xl border bg-border',
            columnClass,
          )}
        >
          {stats.map((stat) => (
            <div key={`${stat.value}-${stat.label}`} className="bg-background p-7">
              <dt className="text-sm text-muted-foreground">{stat.label}</dt>
              <dd className="mt-2 text-4xl font-bold tracking-tight text-primary">{stat.value}</dd>
              {stat.detail ? (
                <p className="mt-2 text-sm text-muted-foreground">{stat.detail}</p>
              ) : null}
            </div>
          ))}
        </dl>
      </div>
    </section>
  )
}

import { Quote, Star } from 'lucide-react'

import { cn } from '@/lib/utils'

export type SpotlightTestimonial = {
  quote: string
  name: string
  role?: string
  company?: string
  avatar?: { src: string; alt: string }
  rating?: number
}

export type TestimonialsSpotlightProps = {
  eyebrow?: string
  title?: string
  featured: SpotlightTestimonial
  items?: SpotlightTestimonial[]
  className?: string
}

function Author({ item }: { item: SpotlightTestimonial }) {
  return (
    <div className="flex items-center gap-3">
      {item.avatar ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={item.avatar.src}
          alt={item.avatar.alt}
          className="size-11 rounded-full object-cover"
        />
      ) : (
        <span className="flex size-11 items-center justify-center rounded-full bg-primary/10 font-semibold text-primary">
          {item.name.charAt(0)}
        </span>
      )}
      <div>
        <p className="font-semibold">{item.name}</p>
        {(item.role || item.company) && (
          <p className="text-sm text-muted-foreground">
            {[item.role, item.company].filter(Boolean).join(' · ')}
          </p>
        )}
      </div>
    </div>
  )
}

export function TestimonialsSpotlight({
  eyebrow = 'Histórias de clientes',
  title = 'Confiança construída em cada entrega.',
  featured,
  items = [],
  className,
}: TestimonialsSpotlightProps) {
  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <header className="mb-10 max-w-2xl">
          <p className="text-sm font-semibold uppercase tracking-[0.18em] text-primary">
            {eyebrow}
          </p>
          <h2 className="mt-3 text-balance text-3xl font-bold tracking-tight md:text-5xl">
            {title}
          </h2>
        </header>

        <div className="grid gap-5 lg:grid-cols-[1.4fr_1fr]">
          <article className="relative overflow-hidden rounded-3xl bg-foreground p-7 text-background md:p-10">
            <Quote className="absolute right-6 top-6 size-20 opacity-10" aria-hidden="true" />
            <div className="mb-8 flex gap-1" aria-label={`${featured.rating ?? 5} de 5 estrelas`}>
              {Array.from({ length: featured.rating ?? 5 }, (_, index) => (
                <Star key={index} className="size-4 fill-current text-amber-400" />
              ))}
            </div>
            <blockquote className="max-w-3xl text-balance text-2xl font-medium leading-relaxed md:text-3xl">
              “{featured.quote}”
            </blockquote>
            <div className="mt-10 [&_*]:text-inherit">
              <Author item={featured} />
            </div>
          </article>

          <div className="grid gap-5">
            {items.slice(0, 2).map((item) => (
              <article
                key={`${item.name}-${item.quote}`}
                className="rounded-3xl border bg-card p-6 shadow-sm transition duration-300 hover:-translate-y-1 hover:shadow-lg motion-reduce:transform-none"
              >
                <blockquote className="mb-6 leading-7 text-muted-foreground">
                  “{item.quote}”
                </blockquote>
                <Author item={item} />
              </article>
            ))}
          </div>
        </div>
      </div>
    </section>
  )
}

import type { LucideIcon } from 'lucide-react'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

export type ContactMethod = {
  label: string
  value: string
  href: string
  icon?: LucideIcon
}

export type ContactSplitSectionProps = {
  eyebrow?: string
  title: string
  description?: string
  methods: ContactMethod[]
  socialLinks?: Array<{ label: string; href: string }>
  form: React.ReactNode
  formTitle?: string
  className?: string
}

export function ContactSplitSection({
  eyebrow = 'Vamos conversar',
  title,
  description,
  methods,
  socialLinks = [],
  form,
  formTitle = 'Conte sobre o seu projeto',
  className,
}: ContactSplitSectionProps) {
  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <div className="overflow-hidden rounded-[2rem] border bg-card shadow-sm">
          <div className="grid lg:grid-cols-[0.85fr_1.15fr]">
            <div className="min-w-0 bg-foreground p-7 text-background md:p-10 lg:p-12">
              <p className="text-sm font-semibold uppercase tracking-[0.18em] text-background/70">
                {eyebrow}
              </p>
              <h2 className="mt-4 text-balance text-3xl font-bold tracking-tight md:text-4xl lg:text-5xl">
                {title}
              </h2>
              {description ? (
                <p className="mt-5 max-w-md leading-7 text-background/70">{description}</p>
              ) : null}

              <address className="mt-10 space-y-3 not-italic">
                {methods.map((method) => {
                  const Icon = method.icon
                  return (
                    <a
                      key={`${method.label}-${method.value}`}
                      href={method.href}
                      className="group flex items-center gap-4 rounded-2xl border border-background/15 p-4 transition hover:bg-background/10"
                    >
                      <span className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-background/10">
                        {Icon ? (
                          <Icon className="size-5" aria-hidden="true" />
                        ) : (
                          <ArrowUpRight className="size-5" />
                        )}
                      </span>
                      <span className="min-w-0">
                        <span className="block text-xs uppercase tracking-wider text-background/55">
                          {method.label}
                        </span>
                        <span className="mt-1 block font-medium [overflow-wrap:anywhere]">
                          {method.value}
                        </span>
                      </span>
                    </a>
                  )
                })}
              </address>

              {socialLinks.length ? (
                <div className="mt-8 flex flex-wrap gap-2">
                  {socialLinks.map((link) => (
                    <a
                      key={link.label}
                      href={link.href}
                      className="rounded-full border border-background/20 px-3 py-1.5 text-sm transition hover:bg-background hover:text-foreground"
                    >
                      {link.label}
                    </a>
                  ))}
                </div>
              ) : null}
            </div>

            <div className="min-w-0 p-7 md:p-10 lg:p-12">
              <h3 className="mb-7 text-2xl font-semibold">{formTitle}</h3>
              {form}
            </div>
          </div>
        </div>
      </div>
    </section>
  )
}

import Image from 'next/image'
import Link from 'next/link'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type HeroImageProps = {
  title: string
  description?: string
  image: { src: string; alt: string }
  eyebrow?: string
  primaryAction?: { label: string; href: string }
  secondaryAction?: { label: string; href: string }
  align?: 'left' | 'center'
  className?: string
}

export function HeroImage({
  title,
  description,
  image,
  eyebrow,
  primaryAction,
  secondaryAction,
  align = 'left',
  className,
}: HeroImageProps) {
  return (
    <section
      className={cn(
        'relative isolate min-h-[560px] overflow-hidden bg-slate-950 text-white',
        className,
      )}
      aria-labelledby="hero-image-title"
    >
      <Image
        src={image.src}
        alt={image.alt}
        fill
        priority
        className="object-cover opacity-55"
        sizes="100vw"
      />
      <div className="absolute inset-0 bg-gradient-to-r from-black/80 via-black/45 to-transparent" />
      <div
        className={cn(
          'container relative z-10 flex min-h-[560px] flex-col justify-center py-20',
          align === 'center' && 'items-center text-center',
        )}
      >
        {eyebrow ? (
          <p className="mb-4 text-sm font-semibold uppercase tracking-[0.2em]">{eyebrow}</p>
        ) : null}
        <h1
          id="hero-image-title"
          className="max-w-4xl text-4xl font-bold tracking-tight sm:text-6xl"
        >
          {title}
        </h1>
        {description ? <p className="mt-6 max-w-2xl text-lg text-white/80">{description}</p> : null}
        {(primaryAction || secondaryAction) && (
          <div className="mt-8 flex flex-wrap gap-3">
            {primaryAction ? (
              <Button asChild size="lg">
                <Link href={primaryAction.href}>{primaryAction.label}</Link>
              </Button>
            ) : null}
            {secondaryAction ? (
              <Button asChild size="lg" variant="secondary">
                <Link href={secondaryAction.href}>{secondaryAction.label}</Link>
              </Button>
            ) : null}
          </div>
        )}
      </div>
    </section>
  )
}

import { cn } from '@/lib/utils'

/** Logo oficial Bloomin (PNG embutido para funcionar no catálogo e nos projetos instalados). */
const BLOOMIN_LOGO_SRC =
  'data:image/png;base64,'

export const BLOOMIN_URL = 'https://bloomin.com.br'

export type BloominLogoProps = {
  className?: string
  /** Altura visual do logo (largura acompanha a proporção). */
  height?: number
}

export function BloominLogo({ className, height = 18 }: BloominLogoProps) {
  return (
    // eslint-disable-next-line @next/next/no-img-element -- data URI portátil no registry
    <img
      src={BLOOMIN_LOGO_SRC}
      alt="Bloomin"
      width={Math.round(height * (421 / 108))}
      height={height}
      className={cn('h-[1.125rem] w-auto', className)}
      style={{ height, width: 'auto' }}
    />
  )
}

export type BloominCreditProps = {
  label?: string
  href?: string
  className?: string
  /** Fundo escuro atrás do logo (o PNG oficial tem fundo preto). */
  logoClassName?: string
}

/** Crédito padrão “Desenvolvido por” com o logo da Bloomin. */
export function BloominCredit({
  label = 'Desenvolvido por',
  href = BLOOMIN_URL,
  className,
  logoClassName,
}: BloominCreditProps) {
  return (
    <span className={cn('inline-flex items-center gap-2 text-sm', className)}>
      <span className="opacity-80">{label}</span>
      <a
        href={href}
        target="_blank"
        rel="noopener noreferrer"
        aria-label="Bloomin — agência de marketing digital"
        className={cn(
          'inline-flex items-center rounded-md bg-neutral-950 px-2 py-1 transition hover:opacity-90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
          logoClassName,
        )}
      >
        <BloominLogo height={16} />
      </a>
    </span>
  )
}

import * as React from 'react'

import { CurrentYear } from '@/components/library/primitives/CurrentYear'
import { cn } from '@/lib/utils'

import { BloominCredit } from './BloominCredit'
import type { FooterColumn, NavigationBrand, NavigationLink, SocialLink } from './types'

export interface FooterColumnsProps extends Omit<React.HTMLAttributes<HTMLElement>, 'children'> {
  brand: NavigationBrand
  description?: React.ReactNode
  columns: readonly FooterColumn[]
  socialLinks?: readonly SocialLink[]
  legalLinks?: readonly NavigationLink[]
  copyright?: React.ReactNode
  navigationLabel?: string
  hideBrandLabel?: boolean
  /** Exibe “Desenvolvido por” com o logo da Bloomin. Padrão: true. */
  showDevelopedBy?: boolean
}

export function FooterColumns({
  brand,
  description,
  columns,
  socialLinks = [],
  legalLinks = [],
  copyright,
  navigationLabel = 'Navegação do rodapé',
  hideBrandLabel = false,
  showDevelopedBy = true,
  className,
  ...props
}: FooterColumnsProps) {
  const columnGrid =
    columns.length >= 4
      ? 'lg:grid-cols-4'
      : columns.length === 3
        ? 'lg:grid-cols-3'
        : columns.length === 2
          ? 'lg:grid-cols-2'
          : 'lg:grid-cols-1'

  return (
    <footer className={cn('border-t bg-muted/30', className)} {...props}>
      <div className="mx-auto grid max-w-7xl gap-10 px-4 py-12 sm:px-6 lg:grid-cols-[minmax(0,1.1fr)_minmax(0,2fr)] lg:px-8 lg:py-16">
        <div>
          <a
            href={brand.href ?? '/'}
            className="inline-flex items-center gap-3 rounded-sm font-semibold tracking-tight focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            {brand.logo}
            <span className={cn(hideBrandLabel && brand.logo && 'sr-only')}>{brand.label}</span>
          </a>
          {description ? (
            <div className="mt-4 max-w-sm text-sm leading-6 text-muted-foreground">
              {description}
            </div>
          ) : null}
          {socialLinks.length ? (
            <ul className="mt-6 flex flex-wrap gap-2" aria-label="Redes sociais">
              {socialLinks.map((link) => (
                <li key={link.href}>
                  <a
                    href={link.href}
                    aria-label={link.label}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex h-10 w-10 items-center justify-center rounded-full border text-muted-foreground transition-colors hover:border-primary hover:text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    {link.icon}
                  </a>
                </li>
              ))}
            </ul>
          ) : null}
        </div>

        <nav className={cn('grid gap-8 sm:grid-cols-2', columnGrid)} aria-label={navigationLabel}>
          {columns.map((column) => (
            <div key={column.title}>
              <h2 className="text-sm font-semibold">{column.title}</h2>
              <ul className="mt-4 space-y-3">
                {column.links.map((link) => (
                  <li key={link.href}>
                    <a
                      href={link.href}
                      target={link.external ? '_blank' : undefined}
                      rel={link.external ? 'noopener noreferrer' : undefined}
                      aria-current={link.current ? 'page' : undefined}
                      className="text-sm text-muted-foreground transition-colors hover:text-foreground focus-visible:rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      {link.label}
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </nav>
      </div>

      <div className="border-t">
        <div className="mx-auto flex max-w-7xl flex-col gap-4 px-4 py-6 text-sm text-muted-foreground sm:px-6 md:flex-row md:items-center md:justify-between lg:px-8">
          <div>
            {copyright ?? (
              <>
                © <CurrentYear /> {brand.label}
              </>
            )}
          </div>
