                    item.current && 'bg-muted text-foreground',
                  )}
                >
                  {item.label}
                </a>
              </li>
            ))}
          </ul>
        </nav>

        {search ? <div className="min-w-0 flex-1 md:ml-auto md:max-w-sm">{search}</div> : null}

